# Utility markdown tables

def md_table(headers, rows):
    def esc(v): return str(v).replace('|','\\|').replace('\n',' ')
    out=['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']
    out += ['| '+' | '.join(esc(x) for x in r)+' |' for r in rows]
    return '\n'.join(out)

