index = '''<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="description" content="Meridian Standard — an AI-native enterprise technology operating standard built around flow with proof.">\n  <title>Meridian Standard — Flow with proof</title>\n  <link rel="stylesheet" href="styles.css">\n</head>\n<body>\n  <header class="nav-wrap">\n    <nav class="nav shell">\n      <a class="brand" href="#top" aria-label="Meridian home"><span class="mark">M</span><span>MERIDIAN</span></a>\n      <div class="nav-links">\n        <a href="#philosophy">Philosophy</a><a href="#model">Operating model</a><a href="#ai">AI</a><a href="#standard">Standard</a><a href="#practices">Practices</a><a href="#profiles">Regulation</a>\n      </div>\n      <a class="pill small" href="SPECIFICATION.md">Read spec</a>\n    </nav>\n  </header>\n\n  <main id="top">\n    <section class="hero shell">\n      <div class="eyebrow">Enterprise technology operating standard · Draft v0.1</div>\n      <h1>Enterprise technology,<br><em>re-industrialised.</em></h1>\n      <p class="lede">Meridian replaces governance theatre with an AI-native control system: persistent crews, paved roads, bounded agents and continuous proof. Move at the speed your risk allows—without choosing between delivery and assurance.</p>\n      <div class="hero-actions"><a class="pill" href="#model">Explore the system</a><a class="text-link" href="SPECIFICATION.md">Full specification →</a></div>\n      <div class="hero-grid">\n        <div><span>01</span><strong>Flow</strong><p>Pull small valuable passages through paved roads.</p></div>\n        <div><span>02</span><strong>Proof</strong><p>Generate regulatory and engineering evidence by construction.</p></div>\n        <div><span>03</span><strong>Agency</strong><p>Give AI authority only where behaviour is bounded and observable.</p></div>\n        <div><span>04</span><strong>Joy</strong><p>Design out status recital, form filling and avoidable cognitive load.</p></div>\n      </div>\n    </section>\n\n    <section id="philosophy" class="section shell">\n      <div class="section-head"><div class="eyebrow">The historical lens</div><h2>Industrial revolutions scale when the <em>system around the machine</em> changes.</h2></div>\n      <div class="history-grid">\n        <article><b>Infrastructure</b><p>Common utilities multiply local invention. Meridian makes platforms the enterprise utility layer.</p></article>\n        <article><b>Standards</b><p>Shared interfaces let independent actors coordinate. Meridian standardises boundaries and evidence, not every local choice.</p></article>\n        <article><b>Measurement</b><p>Instrumentation turns complex systems into controllable systems. Meridian makes telemetry part of governance.</p></article>\n        <article><b>Mechanisation</b><p>Machines absorb repetition; people move toward judgement and new craft. AI follows the same pattern.</p></article>\n        <article><b>Modularity</b><p>Small replaceable parts accelerate improvement and contain failure. Enterprise architecture should do the same.</p></article>\n        <article><b>Organisational redesign</b><p>Electric motors did more when factories stopped imitating line shafts. AI does more when work stops imitating ticket queues.</p></article>\n      </div>\n      <blockquote>“Flow with proof.” <span>The Meridian design constraint</span></blockquote>\n    </section>\n\n    <section id="model" class="section alt">\n      <div class="shell">\n        <div class="section-head"><div class="eyebrow">The operating system</div><h2>Four planes. One digital thread.</h2><p>Separate intent, reusable platform capability, delivery work and assurance—but connect every object so evidence moves with the work.</p></div>\n        <div class="planes">\n          <article><span>01</span><h3>Intent Plane</h3><p>Outcomes, strategy, risk appetite, obligations, capital and Missions.</p></article>\n          <article><span>02</span><h3>Platform Plane</h3><p>Self-service identity, cloud, delivery, observability, data, AI and policy.</p></article>\n          <article><span>03</span><h3>Work Plane</h3><p>Persistent Crews discover, build, run and improve enduring services.</p></article>\n          <article><span>04</span><h3>Proof Plane</h3><p>Controls, evidence, evaluations, exceptions, assurance and replay.</p></article>\n        </div>\n        <div class="thread">\n          <div class="thread-title">THE DIGITAL THREAD</div>\n          <div class="thread-nodes"><span>Obligation</span><i>→</i><span>Control</span><i>→</i><span>Service</span><i>→</i><span>Change</span><i>→</i><span>Evidence</span><i>→</i><span>Outcome</span></div>\n          <p>Ask questions across the whole system instead of reconstructing answers from spreadsheets.</p>\n        </div>\n      </div>\n    </section>\n\n    <section class="section shell">\n      <div class="split">\n        <div><div class="eyebrow">The human system</div><h2>Crews own outcomes.<br>Stewards encode judgement.</h2><p>Persistent multidisciplinary Crews own services end-to-end. Security, privacy, architecture, resilience and risk become Stewardship Circles whose goal is to turn recurring review into policy, patterns and paved roads.</p></div>\n        <div class="roles">\n          <div><strong>Crew</strong><span>Build + run an enduring service or platform</span></div>\n          <div><strong>Steward</strong><span>Named accountable human for a material object</span></div>\n          <div><strong>Circle</strong><span>Encode cross-cutting expertise without becoming a queue</span></div>\n          <div><strong>Guild</strong><span>Grow craft and social learning across Crews</span></div>\n          <div><strong>Swarm</strong><span>Temporary coalition for a cross-cutting Mission</span></div>\n        </div>\n      </div>\n    </section>\n\n    <section id="ai" class="section ai-section">\n      <div class="shell">\n        <div class="section-head"><div class="eyebrow">AI as enterprise utility</div><h2>Not a copilot. A bounded second workforce.</h2><p>Agents can scout, map, make, verify, observe and operate. Authority is granted to a task and environment—not inherited from a model brand.</p></div>\n        <div class="agent-grid">\n          <article><b>Scout</b><p>Research, precedent and change sensing.</p></article><article><b>Cartographer</b><p>System, dependency, data and regulation maps.</p></article><article><b>Maker</b><p>Code, IaC, tests, migrations and runbooks.</p></article><article><b>Verifier</b><p>Evals, policy checks and evidence challenge.</p></article><article><b>Sentinel</b><p>Reliability, security, cost and model behaviour.</p></article><article><b>Operator</b><p>Bounded actions under runtime policy.</p></article>\n        </div>\n        <div class="autonomy" id="autonomy"></div>\n      </div>\n    </section>\n\n    <section id="standard" class="section shell">\n      <div class="section-head"><div class="eyebrow">Normative core</div><h2>A standard you can query.</h2><p>Search the current Meridian clauses by domain, ID or concept. The goal is stable semantics that can be turned into policy and evidence—not another 400-page shelf document.</p></div>\n      <div class="standard-tools"><input id="clauseSearch" type="search" placeholder="Search clauses: resilience, AI, evidence…" aria-label="Search Meridian clauses"><select id="domainFilter" aria-label="Filter by domain"><option value="">All domains</option></select></div>\n      <div id="clauseCount" class="count"></div>\n      <div id="clauseGrid" class="clause-grid"></div>\n    </section>\n\n    <section id="practices" class="section alt">\n      <div class="shell">\n        <div class="section-head"><div class="eyebrow">Practice library</div><h2>Meetings should be worth attending.</h2><p>No mandatory stand-up, sprint ritual or programme increment. Use practices when they create decisions, learning, confidence or human connection.</p></div>\n        <div id="practiceGrid" class="practice-grid"></div>\n      </div>\n    </section>\n\n    <section id="profiles" class="section shell">\n      <div class="section-head"><div class="eyebrow">Applicability compiler</div><h2>One operating system. Many regulatory profiles.</h2><p>Toggle characteristics of an organisation to see which reference profiles become relevant. This is a design aid—not legal advice or a substitute for formal applicability analysis.</p></div>\n      <div class="profile-builder">\n        <div class="checks">\n          <label><input type="checkbox" data-profile="UK-DATA"> Process UK personal data</label>\n          <label><input type="checkbox" data-profile="EU-DATA"> Process EU personal data</label>\n          <label><input type="checkbox" data-profile="EU-AI"> Develop or deploy AI in EU scope</label>\n          <label><input type="checkbox" data-profile="EU-NIS2"> EU essential / important entity</label>\n          <label><input type="checkbox" data-profile="EU-DORA"> EU financial entity in DORA scope</label>\n          <label><input type="checkbox" data-profile="UK-FS"> UK FCA / PRA resilience scope</label>\n          <label><input type="checkbox" data-profile="UK-NIS"> UK NIS / critical digital scope</label>\n          <label><input type="checkbox" data-profile="PAY"> Handle payment-card data</label>\n          <label><input type="checkbox" data-profile="US-PUBLIC"> SEC reporting company</label>\n          <label><input type="checkbox" data-profile="US-HEALTH"> Handle US ePHI in HIPAA scope</label>\n          <label><input type="checkbox" data-profile="AU-APRA"> APRA-regulated entity</label>\n          <label><input type="checkbox" data-profile="CA-OSFI"> OSFI-regulated financial institution</label>\n          <label><input type="checkbox" data-profile="SG-MAS"> MAS-regulated financial institution</label>\n        </div>\n        <div class="profile-output"><div class="mini-label">ACTIVE REFERENCE PROFILES</div><div id="profileOutput"></div></div>\n      </div>\n    </section>\n\n    <section class="section manifesto">\n      <div class="shell">\n        <div class="eyebrow">The 100-year bet</div>\n        <h2>Tools will change. The invariants should not.</h2>\n        <p>Purpose. Small reversible change. Explicit interfaces. Observable systems. Human accountability. Tested resilience. Reusable proof. Continuous learning. These survived steam, electricity and computing—and they are strong bets for whatever follows AI.</p>\n        <a class="pill" href="SPECIFICATION.md">Read the complete Meridian Standard</a>\n      </div>\n    </section>\n  </main>\n\n  <footer><div class="shell footer-grid"><div><div class="brand"><span class="mark">M</span><span>MERIDIAN</span></div><p>Enterprise Technology Operating Standard · Draft v0.1 · 26 Aug 2026</p></div><div><p>Original conceptual framework. Regulatory mappings require qualified legal/compliance validation.</p><a href="regulatory-profiles.json">Profiles JSON</a> · <a href="standard-clauses.json">Clauses JSON</a> · <a href="meridian.schema.json">Schema</a></div></div></footer>\n\n  <script>window.MERIDIAN_CLAUSES = ''' + clause_cards + '''; window.MERIDIAN_PROFILES = ''' + profile_data + '''; window.MERIDIAN_PRACTICES = ''' + practice_data + ''';</script>\n  <script src="app.js"></script>\n</body>\n</html>\n'''
